insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('HRT-301', 'Knows Hiring Inside Out, Has Never Built Software', 'Founder Psychology', 'internal', 'The founder ran recruitment for years and knows exactly what is broken. How long a feature takes, what can be changed safely, and what a promise to a client costs the engineers are things they have never learned, so dates are given out that nobody can meet.', 5, 9, '["Deep HR knowledge, no software sense", "Promises delivery dates without asking", "Cannot judge how long work takes", "Engineers constantly behind"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["hrtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-301-1', (select problem_id from problems where problem_code = 'HRT-301'), 'Build Timelines Never Learned', 'Knowledge', 'Nobody taught the founder how software work is estimated, so a week and a quarter sound equally plausible.', 0.76, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-301-2', (select problem_id from problems where problem_code = 'HRT-301'), 'Selling Is the Comfortable Work', 'Psychological', 'Client conversations feel productive and familiar, so the harder work of understanding the build keeps waiting.', 0.72, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-301-3', (select problem_id from problems where problem_code = 'HRT-301'), 'Saying Yes Feels Like Momentum', 'Behavioural', 'Agreeing to a date wins the meeting, and the cost lands on someone else weeks later.', 0.67, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HRT-301-1', (select problem_id from problems where problem_code = 'HRT-301'), '["RC-HRT-301-1", "RC-HRT-301-2", "RC-HRT-301-3"]'::jsonb, 'Founder Leverage', 'Human Resources & HRTech — Founder Skill Fit', '[]'::jsonb, '["Before your next client promise, ask the person who will build it for a number.", "Write down their number and the date you gave.", "Compare the two after delivery, and use the gap on the next promise."]'::jsonb, '[3, 4, 5]'::jsonb, '["hrtech"]'::jsonb, '["Never give a date you did not get from the person doing the work.", "One measured gap teaches more than a year of guessing."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HRT-301-2', (select problem_id from problems where problem_code = 'HRT-301'), '["RC-HRT-301-1", "RC-HRT-301-2", "RC-HRT-301-3"]'::jsonb, 'Founder Leverage', 'Human Resources & HRTech — Founder Skill Fit', '[]'::jsonb, '["Write the two things this business needs that you have never done.", "Take the bigger one to someone who has shipped software.", "Sit in their planning for a month rather than reading a summary."]'::jsonb, '[3, 4, 5]'::jsonb, '["hrtech"]'::jsonb, '["Name the gap before trying to close it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
