insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('HRT-302', 'The Founder Is Still Doing the Recruiting', 'Founder Psychology', 'internal', 'Clients ask for help filling a role and the founder fills it personally, because they are good at it and it earns money today. The product that would let a hundred clients do it themselves gets the leftover hours.', 5, 9, '["Founder does client recruiting personally", "Service work crowds out product", "Revenue depends on founder hours", "Product progress stalls"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["hrtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-302-1', (select problem_id from problems where problem_code = 'HRT-302'), 'Service Pays Today', 'Behavioural', 'Doing the work by hand brings money this month, so it always wins against product work that pays later.', 0.77, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-302-2', (select problem_id from problems where problem_code = 'HRT-302'), 'No Hours Reserved', 'Operational', 'No time is protected for product, so it only happens when no client is asking.', 0.72, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-302-3', (select problem_id from problems where problem_code = 'HRT-302'), 'Being Needed Feels Good', 'Psychological', 'Clients thanking the founder for a placement is more satisfying than a feature nobody notices.', 0.67, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HRT-302-1', (select problem_id from problems where problem_code = 'HRT-302'), '["RC-HRT-302-1", "RC-HRT-302-2", "RC-HRT-302-3"]'::jsonb, 'Founder Leverage', 'Human Resources & HRTech — Founder Time Use', '[]'::jsonb, '["Write down how much of last month''s revenue needed your hands.", "Pick one part of that work and turn it into something a client can do themselves.", "Measure the same share next month."]'::jsonb, '[3, 4, 5]'::jsonb, '["hrtech"]'::jsonb, '["Revenue that needs your hands does not compound.", "Turn one step into product rather than planning to turn all of it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HRT-302-2', (select problem_id from problems where problem_code = 'HRT-302'), '["RC-HRT-302-1", "RC-HRT-302-2", "RC-HRT-302-3"]'::jsonb, 'Founder Leverage', 'Human Resources & HRTech — Founder Time Use', '[]'::jsonb, '["Write down where your hours went last week, split service and product.", "Decide the split you need for the next quarter and write it down.", "Protect the product hours as firmly as a client call."]'::jsonb, '[3, 4, 5]'::jsonb, '["hrtech"]'::jsonb, '["An unprotected hour goes to whoever is asking loudest."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
