insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('HRT-303', 'Every Client Relationship Runs Through the Founder', 'Founder Psychology', 'internal', 'Clients signed because they trust the founder. Renewals, escalations and new requirements all come to them personally, and nothing about how those conversations go has been written down.', 5, 9, '["All client relationships personal to the founder", "Renewals need the founder", "Nothing written about client handling", "Growth limited by one diary"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["hrtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-303-1', (select problem_id from problems where problem_code = 'HRT-303'), 'Relationships Never Transferred', 'Operational', 'Clients deal with the founder and nobody else has the history or the standing, so handover is impossible.', 0.78, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-303-2', (select problem_id from problems where problem_code = 'HRT-303'), 'Nobody Else Trusted With It', 'Psychological', 'The founder fears an account manager damaging a relationship, so no one is allowed to try.', 0.72, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-303-3', (select problem_id from problems where problem_code = 'HRT-303'), 'No Account Material Exists', 'Knowledge', 'There is nothing a new person could learn an account from, so the dependency has no exit.', 0.67, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HRT-303-1', (select problem_id from problems where problem_code = 'HRT-303'), '["RC-HRT-303-1", "RC-HRT-303-2", "RC-HRT-303-3"]'::jsonb, 'Founder Leverage', 'Human Resources & HRTech — Founder Dependency', '[]'::jsonb, '["Write one page per major client: what they bought, what they complained about, who decides.", "Take one person to your next three client calls, silently.", "Let them run the fourth while you listen and say nothing."]'::jsonb, '[3, 4, 5]'::jsonb, '["hrtech"]'::jsonb, '["A relationship only one person holds is a risk, not an asset.", "Listening without stepping in is the only honest test."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
