insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('HRT-304', 'Product, Sales and Client Delivery Done by the Same Three People', 'Team & Leadership', 'internal', 'The same small team demos the product, builds it, and then does the client''s onboarding by hand. Nobody owns any of the three, so whichever one is on fire gets everyone.', 5, 9, '["Same people do product, sales and delivery", "No owner per function", "Whatever is on fire gets everyone", "Onboarding quality varies"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["hrtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-304-1', (select problem_id from problems where problem_code = 'HRT-304'), 'Roles Never Set', 'Behavioural', 'The team grew by everyone helping with everything rather than by defining jobs, so nothing has an owner.', 0.76, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-304-2', (select problem_id from problems where problem_code = 'HRT-304'), 'Wearing Many Hats Prized', 'Psychological', 'A team where anyone does anything feels resourceful, which hides that no function is owned.', 0.70, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-304-3', (select problem_id from problems where problem_code = 'HRT-304'), 'Handovers Unwritten', 'Operational', 'What must be true before a signed client passes to onboarding was never agreed, so clients fall between.', 0.68, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HRT-304-1', (select problem_id from problems where problem_code = 'HRT-304'), '["RC-HRT-304-1", "RC-HRT-304-2", "RC-HRT-304-3"]'::jsonb, 'Team Effectiveness', 'Human Resources & HRTech — Role Clarity', '[]'::jsonb, '["List the three functions: selling it, building it, onboarding it.", "Put one name against each, even if the same person holds two.", "Write what must be finished before a signed client passes to onboarding."]'::jsonb, '[3, 4, 5]'::jsonb, '["hrtech"]'::jsonb, '["One owner per function, even in a team of three.", "Most clients are lost at the handover, not in the demo."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HRT-304-2', (select problem_id from problems where problem_code = 'HRT-304'), '["RC-HRT-304-1", "RC-HRT-304-2", "RC-HRT-304-3"]'::jsonb, 'Team Effectiveness', 'Human Resources & HRTech — Role Clarity', '[]'::jsonb, '["Pick the function that failed most last quarter.", "Give it one owner and tell the team who it is.", "Review that function alone next quarter."]'::jsonb, '[3, 4, 5]'::jsonb, '["hrtech"]'::jsonb, '["One owner properly assigned beats a reorganisation."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
