insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('HRT-305', 'Nobody Can Agree a Discount or a Custom Feature', 'Team & Leadership', 'internal', 'Sales cannot discount, support cannot promise a fix date, and nobody can say no to a custom request. Everything routes to the founder, who becomes the bottleneck on deals and on the roadmap at the same time.', 5, 9, '["Sales cannot discount", "Custom requests all escalate", "Support cannot commit to anything", "Founder is the bottleneck on deals and roadmap"]'::jsonb, 5, 'Decision Rights', 'decision_rights', '["hrtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-305-1', (select problem_id from problems where problem_code = 'HRT-305'), 'Limits Never Written', 'Operational', 'No one wrote down what may be discounted or promised, so the safe move is always to ask.', 0.77, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-305-2', (select problem_id from problems where problem_code = 'HRT-305'), 'Saying No Feels Like Losing the Deal', 'Psychological', 'Refusing a custom request feels like risking the client, so only the founder will do it.', 0.72, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-305-3', (select problem_id from problems where problem_code = 'HRT-305'), 'Past Decisions Not Turned Into Rules', 'Knowledge', 'The same requests have been decided many times and never written up, so each is reasoned again.', 0.67, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HRT-305-1', (select problem_id from problems where problem_code = 'HRT-305'), '["RC-HRT-305-1", "RC-HRT-305-2", "RC-HRT-305-3"]'::jsonb, 'Team Effectiveness', 'Human Resources & HRTech — Decision Rights', '[]'::jsonb, '["Write the discount rule: how deep, on what contract length, by whom.", "Write the custom-work rule: what is never built, what is built at a price.", "Let the team work inside both for a quarter and review the totals, not each deal."]'::jsonb, '[3, 4, 5]'::jsonb, '["hrtech"]'::jsonb, '["A written rule closes deals faster than a fast approver.", "Review what the rules produced, not each use of them."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HRT-305-2', (select problem_id from problems where problem_code = 'HRT-305'), '["RC-HRT-305-1", "RC-HRT-305-2", "RC-HRT-305-3"]'::jsonb, 'Team Effectiveness', 'Human Resources & HRTech — Decision Rights', '[]'::jsonb, '["List the five requests you get asked about most.", "For each, write who decides and within what limit.", "Put it where sales and support can both see it."]'::jsonb, '[3, 4, 5]'::jsonb, '["hrtech"]'::jsonb, '["Asked five times means a missing rule."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
