insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('HRT-306', 'An HR Company That Hires Badly Itself', 'Team & Leadership', 'internal', 'The irony is not lost on anyone. Roles are filled when the pain gets bad enough, from the founder''s own network, with no written job and no test — which is exactly what the product exists to stop clients doing.', 5, 9, '["Hires only when the pain is bad", "No written job description", "Hires from the founder''s network", "Does the thing the product prevents"]'::jsonb, 5, 'Hiring Repeatability', 'hiring_repeatability', '["hrtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-306-1', (select problem_id from problems where problem_code = 'HRT-306'), 'No Written Role', 'Operational', 'Hiring starts from a shortage rather than a written job, so candidates are judged on rapport.', 0.76, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-306-2', (select problem_id from problems where problem_code = 'HRT-306'), 'Own Advice Not Applied', 'Behavioural', 'The discipline the company sells to clients is never turned inward, because internally it feels like overhead.', 0.73, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-306-3', (select problem_id from problems where problem_code = 'HRT-306'), 'Nothing Learned Between Hires', 'Knowledge', 'What made past hires work is never written down, so the fourth hire is as blind as the first.', 0.67, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HRT-306-1', (select problem_id from problems where problem_code = 'HRT-306'), '["RC-HRT-306-1", "RC-HRT-306-2", "RC-HRT-306-3"]'::jsonb, 'Team Effectiveness', 'Human Resources & HRTech — Hiring Repeatability', '[]'::jsonb, '["Run your own product on your next hire, start to finish.", "Write down where it was awkward.", "Fix those parts in the product, then hire the one after with the fixed version."]'::jsonb, '[3, 4, 5]'::jsonb, '["hrtech"]'::jsonb, '["If your own hiring does not survive your product, neither will a client''s.", "The awkward parts are the roadmap."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
