insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('HRT-307', 'Selling a Platform, Delivering a Service With Software Attached', 'Strategy & Planning', 'internal', 'The pitch is software that scales. The reality is that every client gets manual setup, custom fields and a human doing the work behind the screen. Each accommodation won a deal and together they are an agency.', 5, 9, '["Pitched as platform, delivered as service", "Every client gets custom work", "Manual work behind the product", "Margins look like an agency''s"]'::jsonb, 6, 'Plan and Vision', 'plan_to_vision_alignment', '["hrtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-307-1', (select problem_id from problems where problem_code = 'HRT-307'), 'Plan Never Checked Against the Goal', 'Strategic', 'Nobody holds what is actually delivered against what the company says it sells, so the drift is never seen.', 0.78, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-307-2', (select problem_id from problems where problem_code = 'HRT-307'), 'Each Exception Looked Reasonable', 'Behavioural', 'Every custom accommodation was justified by a deal, and nobody counted them together.', 0.73, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-307-3', (select problem_id from problems where problem_code = 'HRT-307'), 'Goal Never Described as Rules', 'Knowledge', '"A platform" was never written down as things that must be true, so nothing can be tested against it.', 0.67, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HRT-307-1', (select problem_id from problems where problem_code = 'HRT-307'), '["RC-HRT-307-1", "RC-HRT-307-2", "RC-HRT-307-3"]'::jsonb, 'Strategic Focus', 'Human Resources & HRTech — Plan and Vision', '[]'::jsonb, '["Count how many of your clients need manual work every month.", "Work out what share of your costs that is.", "Pick the most common manual step and build it out of existence this quarter."]'::jsonb, '[3, 4, 5]'::jsonb, '["hrtech"]'::jsonb, '["Count the exceptions together; one at a time they all look fine.", "Build the most common one out, not the most annoying one."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HRT-307-2', (select problem_id from problems where problem_code = 'HRT-307'), '["RC-HRT-307-1", "RC-HRT-307-2", "RC-HRT-307-3"]'::jsonb, 'Strategic Focus', 'Human Resources & HRTech — Plan and Vision', '[]'::jsonb, '["Write what \"a platform\" means for you in five specific things.", "Mark which are true today.", "Put the missing ones on the roadmap ahead of new features."]'::jsonb, '[3, 4, 5]'::jsonb, '["hrtech"]'::jsonb, '["A goal you cannot test delivery against is a slogan."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
