insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('HRT-308', 'The Roadmap Is Whatever the Last Client Asked For', 'Strategy & Planning', 'internal', 'Every client request goes on the list and the list has no order. Big clients get their features and the thing that would serve all clients never starts, so the product becomes five clients'' internal tools.', 5, 9, '["Roadmap driven by client requests", "No ranking", "Big clients get their features", "Nothing built for all clients"]'::jsonb, 6, 'Prioritisation', 'prioritization_discipline', '["hrtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-308-1', (select problem_id from problems where problem_code = 'HRT-308'), 'Nothing Ranked', 'Strategic', 'Requests are recorded rather than ordered, so effort follows who asked rather than what is worth building.', 0.77, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-308-2', (select problem_id from problems where problem_code = 'HRT-308'), 'Big Client Requests Feel Non-Negotiable', 'Psychological', 'Saying no to the largest account feels like risking the company, so it is never said.', 0.73, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-308-3', (select problem_id from problems where problem_code = 'HRT-308'), 'Newest Request Wins', 'Behavioural', 'Attention follows the most recent conversation rather than the biggest opportunity.', 0.67, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HRT-308-1', (select problem_id from problems where problem_code = 'HRT-308'), '["RC-HRT-308-1", "RC-HRT-308-2", "RC-HRT-308-3"]'::jsonb, 'Strategic Focus', 'Human Resources & HRTech — Prioritisation', '[]'::jsonb, '["Write every request on one list with who asked and how many clients it would serve.", "Rank by how many clients, not by who asked.", "Build the top two and tell the others what you are not building."]'::jsonb, '[3, 4, 5]'::jsonb, '["hrtech"]'::jsonb, '["Rank by how many it serves, not by who shouted.", "Telling a client no costs less than becoming their dev team."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HRT-308-2', (select problem_id from problems where problem_code = 'HRT-308'), '["RC-HRT-308-1", "RC-HRT-308-2", "RC-HRT-308-3"]'::jsonb, 'Strategic Focus', 'Human Resources & HRTech — Prioritisation', '[]'::jsonb, '["Pick the two things you will stop this week.", "Tell the team and the clients affected.", "Do not start anything new until the top item ships."]'::jsonb, '[3, 4, 5]'::jsonb, '["hrtech"]'::jsonb, '["Stopping is the decision that makes the rest possible."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
