insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('HRT-309', 'Why Each Client Left Is in Somebody''s Memory', 'Strategy & Planning', 'internal', 'Which client churned and why, which onboarding went badly, what the last failed pilot taught — it is in email and in the founder''s head. So the same onboarding mistake is made with the next client.', 5, 9, '["Churn reasons not recorded", "Onboarding failures repeat", "Pilot learnings in email", "Knowledge leaves with people"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["hrtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-309-1', (select problem_id from problems where problem_code = 'HRT-309'), 'Nothing Written Down', 'Operational', 'Why clients left or onboardings failed was never recorded in one place, so the company cannot learn from itself.', 0.78, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-309-2', (select problem_id from problems where problem_code = 'HRT-309'), 'Memory Held by People', 'Knowledge', 'What the company knows about its clients lives in a few heads and a few mailboxes.', 0.72, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HRT-309-3', (select problem_id from problems where problem_code = 'HRT-309'), 'Writing Up a Loss Feels Bad', 'Psychological', 'Recording why a client left feels like documenting a failure, so it is skipped.', 0.67, 'internal', 'Stage 0→1', '["hrtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HRT-309-1', (select problem_id from problems where problem_code = 'HRT-309'), '["RC-HRT-309-1", "RC-HRT-309-2", "RC-HRT-309-3"]'::jsonb, 'Strategic Focus', 'Human Resources & HRTech — What Gets Remembered', '[]'::jsonb, '["Start one page per client that left: what they bought, what went wrong, what they said.", "Fill it in the week they leave, not at quarter end.", "Read the pages before your next onboarding."]'::jsonb, '[3, 4, 5]'::jsonb, '["hrtech"]'::jsonb, '["Write it when it happens or it will not be written.", "The record earns its keep only when read before a decision."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
