insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TRD-301', 'Great at Finding Buyers, Weak on What a Shipment Really Costs', 'Founder Psychology', 'internal', 'The founder can find a buyer in a new country and close the order. Duty, freight, currency movement and the cost of money sitting in a container for six weeks are things they have never added up, so a profitable-looking order loses money.', 5, 9, '["Good at sales, weak on landed cost", "Duty and freight not fully counted", "Currency swings absorbed blindly", "Cannot say which order actually earned"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["trade_import_export"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-301-1', (select problem_id from problems where problem_code = 'TRD-301'), 'Landed Cost Never Learned', 'Knowledge', 'Nobody taught the founder to add duty, freight, finance cost and currency into one number per order.', 0.77, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-301-2', (select problem_id from problems where problem_code = 'TRD-301'), 'Closing Is the Comfortable Work', 'Psychological', 'Winning a buyer feels like the real job, so the arithmetic keeps being left for later.', 0.72, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-301-3', (select problem_id from problems where problem_code = 'TRD-301'), 'Top Line Mistaken for Profit', 'Behavioural', 'Order value is treated as the measure of a good month, so thin orders are celebrated.', 0.68, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRD-301-1', (select problem_id from problems where problem_code = 'TRD-301'), '["RC-TRD-301-1", "RC-TRD-301-2", "RC-TRD-301-3"]'::jsonb, 'Founder Leverage', 'Import / Export & Trade — Founder Skill Fit', '[]'::jsonb, '["Take your last completed order and add every cost: goods, duty, freight, finance, currency loss.", "Compare that to what the buyer paid.", "Do the same for your three biggest orders before you quote the next one."]'::jsonb, '[3, 4, 5]'::jsonb, '["trade_import_export"]'::jsonb, '["Order value is not profit; what is left after duty, freight and finance is.", "Three orders costed properly beats a spreadsheet you do not trust."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRD-301-2', (select problem_id from problems where problem_code = 'TRD-301'), '["RC-TRD-301-1", "RC-TRD-301-2", "RC-TRD-301-3"]'::jsonb, 'Founder Leverage', 'Import / Export & Trade — Founder Skill Fit', '[]'::jsonb, '["Write the two things this business needs that you have never done.", "Take the bigger one to someone who has run trade finance.", "Do it yourself for a quarter before handing it over."]'::jsonb, '[3, 4, 5]'::jsonb, '["trade_import_export"]'::jsonb, '["Name the gap before trying to close it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
