insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TRD-302', 'The Week Goes on Customs, Documents and Chasing Payment', 'Founder Psychology', 'internal', 'A container is held, a document is wrong, a buyer has not paid. The founder spends the week unblocking today''s shipment and never gets to the work that would stop next month''s shipment being held for the same reason.', 5, 9, '["Week spent on customs and documents", "Chasing payment personally", "No time for new markets or systems", "The same document errors repeat"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["trade_import_export"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-302-1', (select problem_id from problems where problem_code = 'TRD-302'), 'Unblocking Instead of Fixing', 'Behavioural', 'Each held shipment is unblocked by hand and the reason documents keep being wrong is never addressed.', 0.76, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-302-2', (select problem_id from problems where problem_code = 'TRD-302'), 'No Hours Reserved', 'Operational', 'No time is protected for process or new markets, so only today''s blockage gets attention.', 0.72, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-302-3', (select problem_id from problems where problem_code = 'TRD-302'), 'Firefighting Feels Like the Job', 'Psychological', 'A day spent freeing a container feels like hard, necessary work, which hides that it is avoidable.', 0.67, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRD-302-1', (select problem_id from problems where problem_code = 'TRD-302'), '["RC-TRD-302-1", "RC-TRD-302-2", "RC-TRD-302-3"]'::jsonb, 'Founder Leverage', 'Import / Export & Trade — Founder Time Use', '[]'::jsonb, '["Write down every held shipment and rejected document for one quarter, and why.", "Group them and fix the cause of the biggest group — a checklist, a different agent, a template.", "Count that group again next quarter."]'::jsonb, '[3, 4, 5]'::jsonb, '["trade_import_export"]'::jsonb, '["A document that is wrong twice is a process gap, not bad luck.", "Count before and after or you will not know it worked."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRD-302-2', (select problem_id from problems where problem_code = 'TRD-302'), '["RC-TRD-302-1", "RC-TRD-302-2", "RC-TRD-302-3"]'::jsonb, 'Founder Leverage', 'Import / Export & Trade — Founder Time Use', '[]'::jsonb, '["Write down where your hours went last week.", "Mark the ones only you could have done.", "Hand documentation to one person with the checklist written."]'::jsonb, '[3, 4, 5]'::jsonb, '["trade_import_export"]'::jsonb, '["Documentation is a checklist job once the checklist exists."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
