insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TRD-303', 'The Buyers and the Agents Only Know the Founder', 'Founder Psychology', 'internal', 'Every buyer, every clearing agent, every supplier relationship is personal. The terms were agreed verbally, the trust is in one person, and none of it is written down anywhere.', 5, 9, '["All relationships personal to the founder", "Terms agreed verbally", "Nothing written about buyers or agents", "Business stops when the founder travels"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["trade_import_export"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-303-1', (select problem_id from problems where problem_code = 'TRD-303'), 'Relationships Not Transferred', 'Operational', 'Buyers and agents deal with the founder personally and nobody else has the terms or the standing.', 0.78, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-303-2', (select problem_id from problems where problem_code = 'TRD-303'), 'Terms Never Written', 'Knowledge', 'What was agreed on price, credit and tolerance lives in memory, so nobody else can honour or enforce it.', 0.73, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-303-3', (select problem_id from problems where problem_code = 'TRD-303'), 'Trust Feels Untransferable', 'Psychological', 'The founder believes the relationship is the trust between two people, so introducing anyone feels like a risk.', 0.67, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRD-303-1', (select problem_id from problems where problem_code = 'TRD-303'), '["RC-TRD-303-1", "RC-TRD-303-2", "RC-TRD-303-3"]'::jsonb, 'Founder Leverage', 'Import / Export & Trade — Founder Dependency', '[]'::jsonb, '["Write one page per buyer and agent: terms, credit days, what they tolerate, who decides.", "Introduce one other person to your three biggest counterparties.", "Let them handle the next routine order end to end."]'::jsonb, '[3, 4, 5]'::jsonb, '["trade_import_export"]'::jsonb, '["A verbal term is not a term once you are not in the room.", "A relationship only one person holds is a risk, not an asset."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
