insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TRD-304', 'Sourcing, Shipping and Collection All Land on Whoever Picks Up', 'Team & Leadership', 'internal', 'Nobody owns sourcing, nobody owns documentation, nobody owns getting paid. Each shipment is handled by whoever was nearest, so when money goes missing there is no one to ask.', 5, 9, '["No owner for sourcing, shipping or collection", "Shipments handled ad hoc", "Unclear who chases payment", "Nobody accountable when money is late"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["trade_import_export"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-304-1', (select problem_id from problems where problem_code = 'TRD-304'), 'Roles Never Set', 'Behavioural', 'The team grew by adding hands to whatever was urgent rather than by defining jobs.', 0.76, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-304-2', (select problem_id from problems where problem_code = 'TRD-304'), 'Everyone Handles Everything', 'Psychological', 'A team where anyone can pick up any shipment feels flexible, which hides that nothing is owned.', 0.70, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-304-3', (select problem_id from problems where problem_code = 'TRD-304'), 'Handovers Unwritten', 'Operational', 'What must be true before a shipment moves from sourcing to shipping to collection was never agreed.', 0.69, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRD-304-1', (select problem_id from problems where problem_code = 'TRD-304'), '["RC-TRD-304-1", "RC-TRD-304-2", "RC-TRD-304-3"]'::jsonb, 'Team Effectiveness', 'Import / Export & Trade — Role Clarity', '[]'::jsonb, '["List the stages: sourcing, documentation, shipping, collection.", "Put one name against each.", "Write what must be complete before each handover, and who checks it."]'::jsonb, '[3, 4, 5]'::jsonb, '["trade_import_export"]'::jsonb, '["One owner per stage, even if one person owns two.", "Money goes missing at the handover, not inside the stage."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
