insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TRD-305', 'No One Can Accept an Order or Extend Credit', 'Team & Leadership', 'internal', 'Whether to take an order at a thinner margin, whether to give a buyer thirty more days, whether to accept a smaller quantity — all of it waits for the founder. In a trade where a day decides whether you get the container, waiting costs orders.', 5, 9, '["All order acceptance needs the founder", "Credit terms decided one by one", "Decisions wait while opportunities pass", "No written margin or credit floor"]'::jsonb, 5, 'Decision Rights', 'decision_rights', '["trade_import_export"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-305-1', (select problem_id from problems where problem_code = 'TRD-305'), 'Limits Never Written', 'Operational', 'No margin floor or credit limit has been written down, so every order needs the only person who knows the rule.', 0.78, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-305-2', (select problem_id from problems where problem_code = 'TRD-305'), 'Each Order Feels Unique', 'Knowledge', 'Because past decisions were never turned into rules, each is reasoned from scratch.', 0.72, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-305-3', (select problem_id from problems where problem_code = 'TRD-305'), 'Risk Feels Too Big to Delegate', 'Psychological', 'Extending credit feels like risking the company, so nobody else is allowed near it.', 0.68, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
