insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TRD-306', 'Hiring on Language and Contacts, Not on Process', 'Team & Leadership', 'internal', 'People are hired because they speak the right language or know a buyer. Useful, and it means nobody was tested on the documentation discipline the business actually runs on, so errors keep coming from the same desk.', 5, 9, '["Hired for contacts or language", "No test of documentation accuracy", "Errors recur from the same people", "No written job description"]'::jsonb, 5, 'Hiring Repeatability', 'hiring_repeatability', '["trade_import_export"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-306-1', (select problem_id from problems where problem_code = 'TRD-306'), 'No Written Role or Test', 'Operational', 'Hiring starts from a contact or a language rather than from the job''s actual daily accuracy demands.', 0.77, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-306-2', (select problem_id from problems where problem_code = 'TRD-306'), 'Contacts Trusted Over Discipline', 'Behavioural', 'A candidate''s buyer list is treated as evidence of competence at everything else.', 0.72, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-306-3', (select problem_id from problems where problem_code = 'TRD-306'), 'Nothing Learned Between Hires', 'Knowledge', 'Who turned out accurate and who did not is never written down, so the pattern is never seen.', 0.67, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRD-306-1', (select problem_id from problems where problem_code = 'TRD-306'), '["RC-TRD-306-1", "RC-TRD-306-2", "RC-TRD-306-3"]'::jsonb, 'Team Effectiveness', 'Import / Export & Trade — Hiring Repeatability', '[]'::jsonb, '["Write the job first: the five things this person must do in month one.", "Make the test a real document set with three errors planted in it.", "Give every candidate the same set and write down what they caught."]'::jsonb, '[3, 4, 5]'::jsonb, '["trade_import_export"]'::jsonb, '["Test the accuracy, not the contacts.", "A planted error tells you more than a CV."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRD-306-2', (select problem_id from problems where problem_code = 'TRD-306'), '["RC-TRD-306-1", "RC-TRD-306-2", "RC-TRD-306-3"]'::jsonb, 'Team Effectiveness', 'Import / Export & Trade — Hiring Repeatability', '[]'::jsonb, '["Look at your last three hires: who was accurate, and what did you see early?", "Turn that into two things you check every time.", "Start looking a quarter before you need the person."]'::jsonb, '[3, 4, 5]'::jsonb, '["trade_import_export"]'::jsonb, '["Hire from a written role, not from a shortage."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
