insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TRD-307', 'Says a Focused Trading House, Takes Whatever Comes', 'Strategy & Planning', 'internal', 'The founder describes a business built on two or three products and known lanes. The order book has eleven products across nine countries, because each one was a real buyer who asked. Nothing has depth anywhere.', 5, 9, '["Says focused, takes everything", "Too many products and lanes", "No depth in any market", "Direction set by whoever asked"]'::jsonb, 6, 'Plan and Vision', 'plan_to_vision_alignment', '["trade_import_export"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-307-1', (select problem_id from problems where problem_code = 'TRD-307'), 'Plan Never Checked Against the Goal', 'Strategic', 'There is no moment where the order book is held against the stated focus, so the spread grows quietly.', 0.78, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-307-2', (select problem_id from problems where problem_code = 'TRD-307'), 'Every Buyer Feels Unmissable', 'Psychological', 'Turning down a real order feels irrational, so focus loses to opportunity every time.', 0.73, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-307-3', (select problem_id from problems where problem_code = 'TRD-307'), 'Focus Never Written as Rules', 'Knowledge', '"Focused" was never written down as which products and which countries, so nothing can be refused on principle.', 0.67, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRD-307-1', (select problem_id from problems where problem_code = 'TRD-307'), '["RC-TRD-307-1", "RC-TRD-307-2", "RC-TRD-307-3"]'::jsonb, 'Strategic Focus', 'Import / Export & Trade — Plan and Vision', '[]'::jsonb, '["Write your focus as specifics: these products, these countries.", "Hold last year''s order book against it and mark what was off-focus.", "Work out what share of your effort went there, and decide the share you want."]'::jsonb, '[3, 4, 5]'::jsonb, '["trade_import_export"]'::jsonb, '["A focus you cannot refuse an order against is a preference.", "Measure the spread before arguing about it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRD-307-2', (select problem_id from problems where problem_code = 'TRD-307'), '["RC-TRD-307-1", "RC-TRD-307-2", "RC-TRD-307-3"]'::jsonb, 'Strategic Focus', 'Import / Export & Trade — Plan and Vision', '[]'::jsonb, '["Take your next off-focus enquiry and write down what saying yes would cost.", "Say no to it once, deliberately.", "Write down what actually happened."]'::jsonb, '[3, 4, 5]'::jsonb, '["trade_import_export"]'::jsonb, '["Refuse one order on purpose and see whether the fear was real."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
