insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TRD-308', 'Three New Markets and a Warehouse, With Payments Outstanding', 'Strategy & Planning', 'internal', 'Two new countries, a new product line and a warehouse decision are all in progress while a large receivable sits uncollected. The collection is the one that decides whether the rest is affordable.', 5, 9, '["Several new markets at once", "Warehouse decision in parallel", "Large receivable uncollected", "Cash problem not prioritised"]'::jsonb, 6, 'Prioritisation', 'prioritization_discipline', '["trade_import_export"]'::jsonb) on conflict (problem_code) do nothing;
