insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TRD-309', 'Which Buyer Paid Late and Which Agent Failed Is Not Written Anywhere', 'Strategy & Planning', 'internal', 'Which buyer disputed on arrival, which agent lost a document, which port takes three weeks in the monsoon — all in memory. So the same buyer gets credit again and the same agent gets the next shipment.', 5, 9, '["Buyer payment history not recorded", "Agent failures not tracked", "Same buyer given credit again", "Seasonal port delays relearned yearly"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["trade_import_export"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-309-1', (select problem_id from problems where problem_code = 'TRD-309'), 'Nothing Written Down', 'Operational', 'Buyer payment behaviour and agent performance were never recorded, so the business cannot learn from its own shipments.', 0.79, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-309-2', (select problem_id from problems where problem_code = 'TRD-309'), 'Memory Held by People', 'Knowledge', 'What the business knows about counterparties lives in a few heads.', 0.73, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRD-309-3', (select problem_id from problems where problem_code = 'TRD-309'), 'Recording a Dispute Feels Like Blame', 'Psychological', 'Writing up a buyer''s bad behaviour feels like damaging a relationship, so it is not written.', 0.66, 'internal', 'Stage 0→1', '["trade_import_export"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRD-309-1', (select problem_id from problems where problem_code = 'TRD-309'), '["RC-TRD-309-1", "RC-TRD-309-2", "RC-TRD-309-3"]'::jsonb, 'Strategic Focus', 'Import / Export & Trade — What Gets Remembered', '[]'::jsonb, '["Start one page per buyer and agent: what was agreed, what happened, how late, what it cost.", "Fill it in the week it happens.", "Read the page before extending credit or booking that agent again."]'::jsonb, '[3, 4, 5]'::jsonb, '["trade_import_export"]'::jsonb, '["A buyer''s payment history is your credit policy.", "Write it when it happens or it will not be written."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRD-309-2', (select problem_id from problems where problem_code = 'TRD-309'), '["RC-TRD-309-1", "RC-TRD-309-2", "RC-TRD-309-3"]'::jsonb, 'Strategic Focus', 'Import / Export & Trade — What Gets Remembered', '[]'::jsonb, '["Write down last year''s three worst shipments and why each went wrong.", "Turn each into a rule: which buyer, which agent, which season.", "Read the rules before the next booking."]'::jsonb, '[3, 4, 5]'::jsonb, '["trade_import_export"]'::jsonb, '["A lesson with no rule attached is a story."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
