insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('MFG-301', 'Can Build Anything, Cannot Say What a Unit Costs', 'Founder Psychology', 'internal', 'The founder is a genuine engineer and the product works. What one unit costs once scrap, rework, machine time and idle labour are counted has never been worked out, so quotes are priced off the material bill and a good order loses money.', 5, 9, '["Strong engineering, weak costing", "Quotes priced off material only", "Scrap and rework not counted", "Cannot say which product earns"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["manufacturing"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-301-1', (select problem_id from problems where problem_code = 'MFG-301'), 'Costing Never Learned', 'Knowledge', 'Nobody taught the founder to build a unit cost including scrap, rework, machine hours and idle time.', 0.77, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-301-2', (select problem_id from problems where problem_code = 'MFG-301'), 'The Shop Floor Is the Comfortable Place', 'Psychological', 'Solving a machining problem feels like real work; sitting with the numbers does not.', 0.72, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-301-3', (select problem_id from problems where problem_code = 'MFG-301'), 'Scrap Treated as Normal', 'Behavioural', 'Rejected parts are accepted as part of the trade rather than counted, so their real cost is never seen.', 0.68, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-MFG-301-1', (select problem_id from problems where problem_code = 'MFG-301'), '["RC-MFG-301-1", "RC-MFG-301-2", "RC-MFG-301-3"]'::jsonb, 'Founder Leverage', 'Industrial & Manufacturing — Founder Skill Fit', '[]'::jsonb, '["Cost one product properly: material, machine hours, labour, scrap, rework.", "Compare that to what you quote for it.", "Do the same for your three highest-volume products before quoting again."]'::jsonb, '[3, 4, 5]'::jsonb, '["manufacturing"]'::jsonb, '["A product that sells well and loses money is your biggest problem.", "Three products costed properly beats a whole catalogue costed roughly."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-MFG-301-2', (select problem_id from problems where problem_code = 'MFG-301'), '["RC-MFG-301-1", "RC-MFG-301-2", "RC-MFG-301-3"]'::jsonb, 'Founder Leverage', 'Industrial & Manufacturing — Founder Skill Fit', '[]'::jsonb, '["Count and weigh your scrap for one month, by product.", "Work out what that month cost you.", "Fix the worst product''s cause and count again."]'::jsonb, '[3, 4, 5]'::jsonb, '["manufacturing"]'::jsonb, '["Scrap is cash on the floor; count it before arguing about it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
