insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('MFG-302', 'The Founder Is On the Floor Fixing Machines', 'Founder Psychology', 'internal', 'A machine is down, an operator is absent, a batch failed inspection. The founder is the best troubleshooter in the building and spends every day proving it, so the work of making the line not need them never starts.', 5, 9, '["Founder troubleshoots daily", "Best operator is the founder", "No time for planning or process", "The same breakdowns repeat"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["manufacturing"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-302-1', (select problem_id from problems where problem_code = 'MFG-302'), 'Fixing Instead of Preventing', 'Behavioural', 'Each breakdown is fixed personally and the reason it keeps breaking is never worked on.', 0.77, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-302-2', (select problem_id from problems where problem_code = 'MFG-302'), 'No Hours Reserved', 'Operational', 'No time is protected for maintenance planning or training, so only today''s stoppage gets attention.', 0.72, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-302-3', (select problem_id from problems where problem_code = 'MFG-302'), 'Being the Best Fixer Feels Necessary', 'Psychological', 'Because the founder genuinely is fastest, stepping back feels like accepting worse output.', 0.68, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-MFG-302-1', (select problem_id from problems where problem_code = 'MFG-302'), '["RC-MFG-302-1", "RC-MFG-302-2", "RC-MFG-302-3"]'::jsonb, 'Founder Leverage', 'Industrial & Manufacturing — Founder Time Use', '[]'::jsonb, '["Write down every stoppage for one month: machine, reason, minutes lost.", "Group them and fix the cause of the biggest group.", "Count the minutes again next month."]'::jsonb, '[3, 4, 5]'::jsonb, '["manufacturing"]'::jsonb, '["A breakdown that repeats is a maintenance gap, not bad luck.", "Count the minutes before and after or you will not know it worked."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-MFG-302-2', (select problem_id from problems where problem_code = 'MFG-302'), '["RC-MFG-302-1", "RC-MFG-302-2", "RC-MFG-302-3"]'::jsonb, 'Founder Leverage', 'Industrial & Manufacturing — Founder Time Use', '[]'::jsonb, '["Write down where your hours went last week.", "Mark the ones only you could have done.", "Train one operator to handle the most common fault, with the steps written."]'::jsonb, '[3, 4, 5]'::jsonb, '["manufacturing"]'::jsonb, '["Being fastest at a fix is the reason to write it down, not to keep doing it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
