insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('MFG-303', 'The Process Is in the Founder''s Hands, Not on Paper', 'Founder Psychology', 'internal', 'Settings, tolerances, which supplier''s material behaves how — all of it is known by feel and none of it is written. So quality moves with the founder''s presence and a second shift is impossible.', 5, 9, '["Machine settings not documented", "Tolerances known by feel", "Quality drops when the founder is away", "Cannot run a second shift"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["manufacturing"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-303-1', (select problem_id from problems where problem_code = 'MFG-303'), 'Process Never Written', 'Knowledge', 'Settings, sequences and tolerances live in the founder''s hands, so consistency depends on them being there.', 0.78, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-303-2', (select problem_id from problems where problem_code = 'MFG-303'), 'Written Process Feels Like Giving It Away', 'Psychological', 'Documenting the method feels like handing over what makes the product good, so it does not get done.', 0.72, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-303-3', (select problem_id from problems where problem_code = 'MFG-303'), 'No Training Material', 'Operational', 'There is nothing an operator could learn the standard from, so the dependency has no exit.', 0.68, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-MFG-303-1', (select problem_id from problems where problem_code = 'MFG-303'), '["RC-MFG-303-1", "RC-MFG-303-2", "RC-MFG-303-3"]'::jsonb, 'Founder Leverage', 'Industrial & Manufacturing — Founder Dependency', '[]'::jsonb, '["Write the setup sheet for your three highest-volume parts: settings, sequence, what to check.", "Have an operator run one from the sheet while you watch and say nothing.", "Fix what the sheet got wrong, not what the operator got wrong."]'::jsonb, '[3, 4, 5]'::jsonb, '["manufacturing"]'::jsonb, '["If they cannot run it from the sheet, the sheet is wrong.", "Watching silently is the only honest test."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-MFG-303-2', (select problem_id from problems where problem_code = 'MFG-303'), '["RC-MFG-303-1", "RC-MFG-303-2", "RC-MFG-303-3"]'::jsonb, 'Founder Leverage', 'Industrial & Manufacturing — Founder Dependency', '[]'::jsonb, '["Write down which supplier''s material behaves how, and what you change for each.", "Put it where the setter works.", "Ask the setter to use it on the next batch without asking you."]'::jsonb, '[3, 4, 5]'::jsonb, '["manufacturing"]'::jsonb, '["What is in your hands serves this shift; what is on paper serves every shift."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
