insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('MFG-304', 'Production, Quality and Maintenance Are the Same People', 'Team & Leadership', 'internal', 'The person who made the part also checks it and also fixes the machine. Nobody owns quality independently, so a bad batch is discovered by the customer rather than on the line.', 5, 9, '["Maker also checks own work", "No independent quality owner", "Maintenance done by whoever is free", "Bad batches found by the customer"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["manufacturing"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-304-1', (select problem_id from problems where problem_code = 'MFG-304'), 'Roles Never Set', 'Behavioural', 'The team grew by adding hands to production rather than by defining quality and maintenance as jobs.', 0.77, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-304-2', (select problem_id from problems where problem_code = 'MFG-304'), 'Self-Checking Feels Efficient', 'Psychological', 'Having the maker check their own work feels like trusting the team, which hides that nobody checks independently.', 0.71, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-304-3', (select problem_id from problems where problem_code = 'MFG-304'), 'Handovers Unwritten', 'Operational', 'What must be true before a batch leaves the line was never agreed, so it leaves unchecked.', 0.69, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-MFG-304-1', (select problem_id from problems where problem_code = 'MFG-304'), '["RC-MFG-304-1", "RC-MFG-304-2", "RC-MFG-304-3"]'::jsonb, 'Team Effectiveness', 'Industrial & Manufacturing — Role Clarity', '[]'::jsonb, '["Name one person who checks work they did not make, even part-time.", "Write the three things they check before a batch moves.", "Count how many bad batches the customer finds, before and after."]'::jsonb, '[3, 4, 5]'::jsonb, '["manufacturing"]'::jsonb, '["Nobody can inspect their own work honestly; it is not about trust.", "Count customer-found defects or you cannot tell if it worked."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-MFG-304-2', (select problem_id from problems where problem_code = 'MFG-304'), '["RC-MFG-304-1", "RC-MFG-304-2", "RC-MFG-304-3"]'::jsonb, 'Team Effectiveness', 'Industrial & Manufacturing — Role Clarity', '[]'::jsonb, '["List the jobs that must happen whoever is on shift: setup, check, maintenance, records.", "Put one name against each.", "Write what must be done at shift handover."]'::jsonb, '[3, 4, 5]'::jsonb, '["manufacturing"]'::jsonb, '["Own the job, not the shift."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
