insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('MFG-305', 'Nobody Can Stop the Line or Accept a Deviation', 'Team & Leadership', 'internal', 'An operator who sees something wrong cannot stop the line, and a supervisor cannot accept a part slightly out of tolerance. Both wait for the founder, so bad parts keep being made while the phone rings.', 5, 9, '["Operators cannot stop the line", "Deviations wait for the founder", "Bad parts made while waiting", "No written tolerance authority"]'::jsonb, 5, 'Decision Rights', 'decision_rights', '["manufacturing"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-305-1', (select problem_id from problems where problem_code = 'MFG-305'), 'Limits Never Written', 'Operational', 'No one wrote down who may stop production or accept a deviation, so nobody does either.', 0.78, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-305-2', (select problem_id from problems where problem_code = 'MFG-305'), 'Stopping Feels Expensive', 'Psychological', 'A stopped line is a visible cost and scrap is an invisible one, so nobody is empowered to stop.', 0.73, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
