insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('MFG-307', 'Wants Volume Manufacturing, Runs a Job Shop', 'Strategy & Planning', 'internal', 'The founder talks about volume contracts, and the shop takes every one-off job that comes because it pays this month. Every job is a different setup, so the line never gets good at anything and volume work is out of reach.', 5, 9, '["Wants volume, takes one-offs", "Every job a different setup", "No repeatable production", "Volume contracts unreachable"]'::jsonb, 6, 'Plan and Vision', 'plan_to_vision_alignment', '["manufacturing"]'::jsonb) on conflict (problem_code) do nothing;
