insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('MFG-308', 'A New Machine, a Certification and a New Customer, All at Once', 'Strategy & Planning', 'internal', 'A capital purchase, a quality certification and onboarding a large customer are running together. The certification is the one the large customer will ask for, and it is getting the same attention as the rest.', 5, 9, '["Capital purchase and certification together", "Large customer onboarding in parallel", "Certification not prioritised", "Everything half-done"]'::jsonb, 6, 'Prioritisation', 'prioritization_discipline', '["manufacturing"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-308-1', (select problem_id from problems where problem_code = 'MFG-308'), 'Nothing Ranked', 'Strategic', 'Work is listed rather than ordered, so a gating certification competes equally with a machine purchase.', 0.78, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-308-2', (select problem_id from problems where problem_code = 'MFG-308'), 'Blocking Work Not Identified', 'Knowledge', 'Nobody wrote down which piece of work gates the others, so it is not treated differently.', 0.72, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-308-3', (select problem_id from problems where problem_code = 'MFG-308'), 'Buying Feels Like Progress', 'Psychological', 'A new machine is visible progress; a certification file is invisible, so the machine gets the attention.', 0.68, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-MFG-308-1', (select problem_id from problems where problem_code = 'MFG-308'), '["RC-MFG-308-1", "RC-MFG-308-2", "RC-MFG-308-3"]'::jsonb, 'Strategic Focus', 'Industrial & Manufacturing — Prioritisation', '[]'::jsonb, '["Write down which single piece of work, if late, delays everything else.", "Give it your best person and protect them from the rest.", "Delay whatever competes with it, and say so out loud."]'::jsonb, '[3, 4, 5]'::jsonb, '["manufacturing"]'::jsonb, '["One gate first; everything behind it is waiting anyway.", "Say what is delayed or it continues quietly."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-MFG-308-2', (select problem_id from problems where problem_code = 'MFG-308'), '["RC-MFG-308-1", "RC-MFG-308-2", "RC-MFG-308-3"]'::jsonb, 'Strategic Focus', 'Industrial & Manufacturing — Prioritisation', '[]'::jsonb, '["List everything running and what each needs from your scarcest person.", "Rank by what unblocks the most.", "Pause the bottom two this week."]'::jsonb, '[3, 4, 5]'::jsonb, '["manufacturing"]'::jsonb, '["Rank by what unblocks, not by what is visible."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
