insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('MFG-309', 'Every Batch Problem Is Solved From Scratch', 'Strategy & Planning', 'internal', 'Which supplier''s material cracked, what setting fixed the finish problem last year, which customer''s drawing is always wrong — all in a few heads. So the same problem is diagnosed again, expensively, by the same person.', 5, 9, '["Material problems not recorded", "Fixes rediscovered each time", "Customer drawing issues relearned", "Knowledge leaves with people"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["manufacturing"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-309-1', (select problem_id from problems where problem_code = 'MFG-309'), 'Nothing Written Down', 'Operational', 'Faults, causes and fixes were never recorded, so the shop rediscovers its own solutions.', 0.79, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-309-2', (select problem_id from problems where problem_code = 'MFG-309'), 'Memory Held by People', 'Knowledge', 'What the shop knows lives in a few experienced heads and walks out when they do.', 0.73, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MFG-309-3', (select problem_id from problems where problem_code = 'MFG-309'), 'Recording a Fault Feels Like Blame', 'Psychological', 'Writing up a bad batch feels like finding fault with the shift, so it is skipped.', 0.66, 'internal', 'Stage 0→1', '["manufacturing"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-MFG-309-1', (select problem_id from problems where problem_code = 'MFG-309'), '["RC-MFG-309-1", "RC-MFG-309-2", "RC-MFG-309-3"]'::jsonb, 'Strategic Focus', 'Industrial & Manufacturing — What Gets Remembered', '[]'::jsonb, '["Start one page per recurring fault: what it looks like, what causes it, what fixes it.", "Fill it in the day it happens, on the floor, not in an office later.", "Put the pages where the setter works."]'::jsonb, '[3, 4, 5]'::jsonb, '["manufacturing"]'::jsonb, '["A fix nobody wrote down will be rediscovered at full price.", "Write it on the floor or it will not be written."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-MFG-309-2', (select problem_id from problems where problem_code = 'MFG-309'), '["RC-MFG-309-1", "RC-MFG-309-2", "RC-MFG-309-3"]'::jsonb, 'Strategic Focus', 'Industrial & Manufacturing — What Gets Remembered', '[]'::jsonb, '["Write one page per supplier: what their material did and when.", "Read it before the next purchase order.", "Turn the worst pattern into a purchasing rule."]'::jsonb, '[3, 4, 5]'::jsonb, '["manufacturing"]'::jsonb, '["A lesson with no rule attached is a story."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
