insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('SAS-301', 'Can Build It, Has Never Sold It', 'Founder Psychology', 'internal', 'The founder is a strong engineer and the product is real. Finding who buys, running a call that ends in a decision, and asking for money are things they have never done, so the product keeps improving and the pipeline stays empty.', 5, 9, '["Strong technical, no selling experience", "Product improves, pipeline does not", "Has never asked for money directly", "Cannot say who the buyer is"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["saas"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-301-1', (select problem_id from problems where problem_code = 'SAS-301'), 'Selling Never Learned', 'Knowledge', 'Nobody taught the founder how to run a sales conversation, so every call becomes a demo and ends politely.', 0.77, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-301-2', (select problem_id from problems where problem_code = 'SAS-301'), 'Building Is the Safe Place', 'Psychological', 'Code has a clear finish line and no rejection in it, so the next feature always wins over the next call.', 0.73, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-301-3', (select problem_id from problems where problem_code = 'SAS-301'), 'Improving the Product Feels Like Progress on Sales', 'Behavioural', 'Each new feature is treated as the thing that will make selling easier, which postpones selling indefinitely.', 0.68, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SAS-301-1', (select problem_id from problems where problem_code = 'SAS-301'), '["RC-SAS-301-1", "RC-SAS-301-2", "RC-SAS-301-3"]'::jsonb, 'Founder Leverage', 'Information Technology & Software (SaaS) — Founder Skill Fit', '[]'::jsonb, '["Book three calls this week with people who could actually pay.", "In each one, ask for the order before you leave the call.", "Write down exactly what they said no to."]'::jsonb, '[3, 4, 5]'::jsonb, '["saas"]'::jsonb, '["You cannot learn selling by building.", "A recorded no is worth more than a polite maybe."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SAS-301-2', (select problem_id from problems where problem_code = 'SAS-301'), '["RC-SAS-301-1", "RC-SAS-301-2", "RC-SAS-301-3"]'::jsonb, 'Founder Leverage', 'Information Technology & Software (SaaS) — Founder Skill Fit', '[]'::jsonb, '["Write the two things this business needs that you have never done.", "Take the bigger one to someone who has sold software.", "Sit on their calls for a month rather than reading advice."]'::jsonb, '[3, 4, 5]'::jsonb, '["saas"]'::jsonb, '["Name the gap before trying to close it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
