insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('SAS-302', 'The Founder Is Still the Main Developer', 'Founder Psychology', 'internal', 'Features, bugs and deployments take the founder''s week because they are fastest at them. Deciding who this is for and what not to build has no hours left, so the product grows in every direction at once.', 5, 9, '["Founder codes most of the week", "Deploys and bugs handled personally", "No hours for direction", "Product grows in all directions"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["saas"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-302-1', (select problem_id from problems where problem_code = 'SAS-302'), 'Fastest Person Does the Work', 'Behavioural', 'The founder is quickest at the technical work, so it keeps landing on them and never gets handed over.', 0.76, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-302-2', (select problem_id from problems where problem_code = 'SAS-302'), 'No Hours Reserved', 'Operational', 'No time is protected for direction or for talking to users, so only the build gets attention.', 0.72, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-302-3', (select problem_id from problems where problem_code = 'SAS-302'), 'Coding Has a Finish Line', 'Psychological', 'Shipping a feature feels finished; deciding direction never does, so the code wins the day.', 0.68, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SAS-302-1', (select problem_id from problems where problem_code = 'SAS-302'), '["RC-SAS-302-1", "RC-SAS-302-2", "RC-SAS-302-3"]'::jsonb, 'Founder Leverage', 'Information Technology & Software (SaaS) — Founder Time Use', '[]'::jsonb, '["Write down where your hours went last week.", "Mark the hours only a founder could have spent.", "Protect one full day a week for those and hold it."]'::jsonb, '[3, 4, 5]'::jsonb, '["saas"]'::jsonb, '["Being fastest at a task is the reason to hand it over, not to keep it.", "A protected day survives; a good intention does not."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SAS-302-2', (select problem_id from problems where problem_code = 'SAS-302'), '["RC-SAS-302-1", "RC-SAS-302-2", "RC-SAS-302-3"]'::jsonb, 'Founder Leverage', 'Information Technology & Software (SaaS) — Founder Time Use', '[]'::jsonb, '["Pick the technical job you do most often.", "Write down the steps you actually follow.", "Hand it over and answer questions for two weeks, then stop."]'::jsonb, '[3, 4, 5]'::jsonb, '["saas"]'::jsonb, '["Write the steps before handing over, or it comes straight back."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
