insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('SAS-303', 'Every Demo, Every Decision, Every Deploy Needs the Founder', 'Founder Psychology', 'internal', 'Nobody else can demo the product, nobody else decides what goes in a release, and nobody else can deploy it. The product knowledge was never written down, so the company runs at the speed of one person.', 5, 9, '["Only the founder can demo", "Release decisions all founder-made", "Only the founder can deploy", "Nothing written down"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["saas"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-303-1', (select problem_id from problems where problem_code = 'SAS-303'), 'Product Knowledge Never Written', 'Knowledge', 'How the product works and why it was built this way lives in the founder''s head and nowhere else.', 0.78, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-303-2', (select problem_id from problems where problem_code = 'SAS-303'), 'Approval Used as Quality Control', 'Behavioural', 'The founder''s review is the only check, so removing it feels like removing quality rather than replacing it.', 0.72, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-303-3', (select problem_id from problems where problem_code = 'SAS-303'), 'Nobody Else Trusted With a Demo', 'Psychological', 'The founder fears someone demoing it badly more than the cost of being the only one who can.', 0.68, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SAS-303-1', (select problem_id from problems where problem_code = 'SAS-303'), '["RC-SAS-303-1", "RC-SAS-303-2", "RC-SAS-303-3"]'::jsonb, 'Founder Leverage', 'Information Technology & Software (SaaS) — Founder Dependency', '[]'::jsonb, '["Write the demo as a script: what you show, in what order, what you say.", "Have someone else run it for a friendly prospect while you listen silently.", "Fix what the script got wrong, not what the person got wrong."]'::jsonb, '[3, 4, 5]'::jsonb, '["saas"]'::jsonb, '["If they cannot demo from the script, the script is wrong.", "Listening without interrupting is the only honest test."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SAS-303-2', (select problem_id from problems where problem_code = 'SAS-303'), '["RC-SAS-303-1", "RC-SAS-303-2", "RC-SAS-303-3"]'::jsonb, 'Founder Leverage', 'Information Technology & Software (SaaS) — Founder Dependency', '[]'::jsonb, '["Write down the deploy steps exactly as you do them.", "Have someone else deploy while you watch.", "Write down every question they had to ask, and add each to the steps."]'::jsonb, '[3, 4, 5]'::jsonb, '["saas"]'::jsonb, '["The questions they ask are the missing documentation."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
