insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('SAS-304', 'Everyone Is Full-Stack and Nobody Owns the Customer', 'Team & Leadership', 'internal', 'The same few people build, support, and occasionally sell. It worked at three customers. Now nobody owns whether a customer is succeeding, so churn arrives as a surprise.', 5, 9, '["Everyone does everything", "Nobody owns the customer", "Support handled by whoever notices", "Churn arrives as a surprise"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["saas"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-304-1', (select problem_id from problems where problem_code = 'SAS-304'), 'Roles Never Set', 'Behavioural', 'The team grew by everyone helping with everything rather than by defining jobs, so the customer has no owner.', 0.77, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-304-2', (select problem_id from problems where problem_code = 'SAS-304'), 'Full-Stack Culture Prized', 'Psychological', 'Everyone doing everything feels like a strong small team, which hides that nobody is accountable for retention.', 0.70, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-304-3', (select problem_id from problems where problem_code = 'SAS-304'), 'Handovers Unwritten', 'Operational', 'What must be true before a signed customer is considered onboarded was never agreed.', 0.68, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SAS-304-1', (select problem_id from problems where problem_code = 'SAS-304'), '["RC-SAS-304-1", "RC-SAS-304-2", "RC-SAS-304-3"]'::jsonb, 'Team Effectiveness', 'Information Technology & Software (SaaS) — Role Clarity', '[]'::jsonb, '["Name one person who owns whether customers are succeeding.", "Write the three signals they watch weekly.", "Review those signals with them every week, by name of customer."]'::jsonb, '[3, 4, 5]'::jsonb, '["saas"]'::jsonb, '["If nobody owns retention, retention is nobody''s surprise but yours.", "Review customers by name, not as a number."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SAS-304-2', (select problem_id from problems where problem_code = 'SAS-304'), '["RC-SAS-304-1", "RC-SAS-304-2", "RC-SAS-304-3"]'::jsonb, 'Team Effectiveness', 'Information Technology & Software (SaaS) — Role Clarity', '[]'::jsonb, '["List what has to happen every week now that you have paying customers.", "Put one name against each.", "Write what must be finished before a signed customer counts as onboarded."]'::jsonb, '[3, 4, 5]'::jsonb, '["saas"]'::jsonb, '["A paying customer is a job, not an afterthought."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
