insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('SAS-305', 'Nobody Can Price, Discount or Promise a Date', 'Team & Leadership', 'internal', 'Sales cannot set a price, support cannot promise a fix, and nobody can commit to a feature. It all routes to the founder, so deals slow down and customers hear nothing while they wait.', 5, 9, '["Pricing decided only by the founder", "No one can promise a fix date", "Deals slow while waiting", "Customers hear nothing"]'::jsonb, 5, 'Decision Rights', 'decision_rights', '["saas"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-305-1', (select problem_id from problems where problem_code = 'SAS-305'), 'Limits Never Written', 'Operational', 'No one wrote down what may be priced, discounted or promised, so the safe move is always to ask.', 0.78, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-305-2', (select problem_id from problems where problem_code = 'SAS-305'), 'Pricing Feels Too Delicate to Delegate', 'Psychological', 'The founder believes a wrong price could damage the business, so nobody else is allowed near it.', 0.72, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-305-3', (select problem_id from problems where problem_code = 'SAS-305'), 'Past Decisions Not Turned Into Rules', 'Knowledge', 'The same pricing situations have been decided repeatedly and never written up, so each is reasoned again.', 0.67, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SAS-305-1', (select problem_id from problems where problem_code = 'SAS-305'), '["RC-SAS-305-1", "RC-SAS-305-2", "RC-SAS-305-3"]'::jsonb, 'Team Effectiveness', 'Information Technology & Software (SaaS) — Decision Rights', '[]'::jsonb, '["Write the price list and the discount rule: how deep, for what commitment, by whom.", "Write what support may promise without asking.", "Let the team work inside both for a quarter and review the totals, not each deal."]'::jsonb, '[3, 4, 5]'::jsonb, '["saas"]'::jsonb, '["A written rule closes deals faster than a fast approver.", "Review what the rules produced, not each use of them."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
