insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('SAS-306', 'Hiring Engineers From Friends, With No Test', 'Team & Leadership', 'internal', 'Hires come from the founder''s network and are judged on a conversation. Culture is good and nobody was tested on the work, so the gaps the team already has stay exactly where they are.', 5, 9, '["Hires from the founder''s network", "Judged on conversation, not work", "No written job description", "Existing skill gaps persist"]'::jsonb, 5, 'Hiring Repeatability', 'hiring_repeatability', '["saas"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-306-1', (select problem_id from problems where problem_code = 'SAS-306'), 'No Written Role or Test', 'Operational', 'Hiring starts from a person being available rather than from a written job with a way to test it.', 0.76, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
