insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-306-3', (select problem_id from problems where problem_code = 'SAS-306'), 'Same Network, Same Gaps', 'Strategic', 'Hiring from one circle reproduces its blind spots, so the skills the team lacks stay lacking.', 0.68, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
