insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('SAS-307', 'Building for Everyone, Which Means for Nobody', 'Strategy & Planning', 'internal', 'The founder describes a product for a specific kind of company, and the feature list serves three completely different kinds because each asked. Every addition was justified and together they are a product with no obvious buyer.', 5, 9, '["Says one customer type, serves three", "Feature list has no shape", "Cannot describe the buyer precisely", "Positioning changes by conversation"]'::jsonb, 6, 'Plan and Vision', 'plan_to_vision_alignment', '["saas"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-307-1', (select problem_id from problems where problem_code = 'SAS-307'), 'Plan Never Checked Against the Goal', 'Strategic', 'Nobody holds the roadmap against the stated customer, so the product drifts toward whoever asks loudest.', 0.78, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-307-2', (select problem_id from problems where problem_code = 'SAS-307'), 'Every Request Feels Like Validation', 'Psychological', 'Any interest from anyone is read as proof the product is working, so nothing is refused.', 0.73, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-307-3', (select problem_id from problems where problem_code = 'SAS-307'), 'Buyer Never Described Properly', 'Knowledge', 'The target customer is a category rather than a described company with a named problem, so nothing can be tested against it.', 0.68, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
