insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('SAS-308', 'The Roadmap Is Every Request Anyone Has Made', 'Strategy & Planning', 'internal', 'Customer asks, investor suggestions, a rewrite and three integrations all sit on the same list in no order. Everything is in progress, nothing ships, and the one thing that would win deals is somewhere in the middle.', 5, 9, '["Roadmap is an unranked list", "Everything in progress", "Nothing ships", "The deal-winning feature buried"]'::jsonb, 6, 'Prioritisation', 'prioritization_discipline', '["saas"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-308-1', (select problem_id from problems where problem_code = 'SAS-308'), 'Nothing Ranked', 'Strategic', 'The roadmap records requests rather than ordering them, so effort spreads across items of very different value.', 0.77, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-308-2', (select problem_id from problems where problem_code = 'SAS-308'), 'Saying No Feels Like Losing the Customer', 'Psychological', 'Refusing a request from a paying customer feels like risking them, so nothing is refused.', 0.73, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-308-3', (select problem_id from problems where problem_code = 'SAS-308'), 'Newest Request Wins', 'Behavioural', 'Attention follows the most recent conversation rather than the biggest opportunity.', 0.67, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SAS-308-1', (select problem_id from problems where problem_code = 'SAS-308'), '["RC-SAS-308-1", "RC-SAS-308-2", "RC-SAS-308-3"]'::jsonb, 'Strategic Focus', 'Information Technology & Software (SaaS) — Prioritisation', '[]'::jsonb, '["Write everything on the roadmap in one list.", "Rank it by one question: what will win or keep the most customers next quarter?", "Work the top two only, and tell everyone else what you are not doing."]'::jsonb, '[3, 4, 5]'::jsonb, '["saas"]'::jsonb, '["Ranking is the work; collecting requests is not.", "Telling a customer no costs less than becoming their dev team."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SAS-308-2', (select problem_id from problems where problem_code = 'SAS-308'), '["RC-SAS-308-1", "RC-SAS-308-2", "RC-SAS-308-3"]'::jsonb, 'Strategic Focus', 'Information Technology & Software (SaaS) — Prioritisation', '[]'::jsonb, '["Pick the two things you will stop this week.", "Tell the team they are stopped.", "Do not start anything new until the top item ships."]'::jsonb, '[3, 4, 5]'::jsonb, '["saas"]'::jsonb, '["Stopping is the decision that makes the rest possible."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
