insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('SAS-309', 'Why Customers Left Is in Somebody''s Memory', 'Strategy & Planning', 'internal', 'Which customer churned and why, what the last pricing experiment did, which onboarding failed — the results are in a chat thread and one person''s head. So the same failed idea gets tried again next year.', 5, 9, '["Churn reasons not recorded", "Experiment results in chat threads", "Failed ideas retried", "Knowledge leaves with people"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["saas"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-309-1', (select problem_id from problems where problem_code = 'SAS-309'), 'Nothing Written Down', 'Operational', 'Why customers left and what each experiment did were never recorded in one place, so the company cannot learn from itself.', 0.79, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-309-2', (select problem_id from problems where problem_code = 'SAS-309'), 'Memory Held by People', 'Knowledge', 'What the company knows lives in a few heads and in unsearchable chat history.', 0.73, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-SAS-309-3', (select problem_id from problems where problem_code = 'SAS-309'), 'Writing Up a Loss Feels Bad', 'Psychological', 'Recording why a customer left feels like documenting a failure, so it is skipped.', 0.67, 'internal', 'Stage 0→1', '["saas"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SAS-309-1', (select problem_id from problems where problem_code = 'SAS-309'), '["RC-SAS-309-1", "RC-SAS-309-2", "RC-SAS-309-3"]'::jsonb, 'Strategic Focus', 'Information Technology & Software (SaaS) — What Gets Remembered', '[]'::jsonb, '["Start one page per customer that left: what they bought, what went wrong, what they said.", "Fill it in the week they leave, not at quarter end.", "Read the pages before your next onboarding or pricing change."]'::jsonb, '[3, 4, 5]'::jsonb, '["saas"]'::jsonb, '["Write it when it happens or it will not be written.", "The record earns its keep only when read before a decision."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-SAS-309-2', (select problem_id from problems where problem_code = 'SAS-309'), '["RC-SAS-309-1", "RC-SAS-309-2", "RC-SAS-309-3"]'::jsonb, 'Strategic Focus', 'Information Technology & Software (SaaS) — What Gets Remembered', '[]'::jsonb, '["Write up your three biggest experiments and what each did.", "Turn each into an instruction for next time.", "Read them at the start of the next planning round."]'::jsonb, '[3, 4, 5]'::jsonb, '["saas"]'::jsonb, '["A lesson with no instruction attached is a story."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
