insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('LGL-301', 'A Fine Lawyer Who Has Never Priced a Product', 'Founder Psychology', 'internal', 'The founder knows exactly which legal work is wasteful and has built something that removes it. Pricing software, rather than billing by the hour, is a skill they have never had — so the product is priced like a junior''s time and leaves money on the table.', 5, 9, '["Deep legal knowledge, no product pricing sense", "Priced like billable hours", "Cannot say what the product is worth to a buyer", "Leaves money on the table"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["legaltech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LGL-301-1', (select problem_id from problems where problem_code = 'LGL-301'), 'Product Pricing Never Learned', 'Knowledge', 'Nobody taught the founder to price on the value delivered rather than on the hours replaced.', 0.77, 'internal', 'Stage 0→1', '["legaltech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LGL-301-2', (select problem_id from problems where problem_code = 'LGL-301'), 'Legal Work Is the Comfortable Ground', 'Psychological', 'Talking about the law feels expert and familiar; pricing conversations feel like guessing.', 0.72, 'internal', 'Stage 0→1', '["legaltech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LGL-301-3', (select problem_id from problems where problem_code = 'LGL-301'), 'Hourly Thinking Carried Over', 'Behavioural', 'Years of billing time makes cost-plus feel like the only honest way to price.', 0.68, 'internal', 'Stage 0→1', '["legaltech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-LGL-301-1', (select problem_id from problems where problem_code = 'LGL-301'), '["RC-LGL-301-1", "RC-LGL-301-2", "RC-LGL-301-3"]'::jsonb, 'Founder Leverage', 'Legal & LegalTech — Founder Skill Fit', '[]'::jsonb, '["Work out what your product saves a client in a year, in hours and in money.", "Price against that, not against what it costs you.", "Test the new price on the next three prospects and write down what they said."]'::jsonb, '[3, 4, 5]'::jsonb, '["legaltech"]'::jsonb, '["Price on what it saves them, not on what it costs you.", "Three real reactions beat a month of deliberating."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
