insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('LGL-302', 'Still Practising Law and Running the Company', 'Founder Psychology', 'internal', 'Client matters have deadlines with courts attached and the product does not, so the practice always wins the week. The company work happens at night and slips whenever a matter gets busy.', 5, 9, '["Legal practice competes with the company", "Court deadlines always win", "Company work done at night", "Nothing has protected time"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["legaltech"]'::jsonb) on conflict (problem_code) do nothing;
