insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('LGL-303', 'Only the Founder Can Answer a Legal Question About the Product', 'Founder Psychology', 'internal', 'Every prospect asks whether the output is defensible, and only the founder can answer. The reasoning was never written down, so the founder is in every sales call and every support escalation.', 5, 9, '["Founder in every sales call", "Legal reasoning unwritten", "Support escalations all reach the founder", "Growth limited by one diary"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["legaltech"]'::jsonb) on conflict (problem_code) do nothing;
