insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LGL-303-2', (select problem_id from problems where problem_code = 'LGL-303'), 'Nobody Else Trusted With It', 'Psychological', 'The founder fears a non-lawyer saying something wrong about the law, so nobody is allowed to try.', 0.73, 'internal', 'Stage 0→1', '["legaltech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LGL-303-3', (select problem_id from problems where problem_code = 'LGL-303'), 'No Training Material Exists', 'Operational', 'There is nothing a new person could learn the legal case from, so the dependency has no exit.', 0.67, 'internal', 'Stage 0→1', '["legaltech"]'::jsonb) on conflict (root_cause_code) do nothing;
