insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('LGL-304', 'Legal Review and Product Decisions Blur Together', 'Team & Leadership', 'internal', 'The founder comments on the interface, the engineer decides what the output says, and nobody owns whether a claim about the product is legally safe. On paper these have owners; in practice they do not.', 5, 9, '["Legal and product decisions blur", "Nobody owns claim accuracy", "Engineers decide legal wording", "Ownership unclear under scrutiny"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["legaltech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LGL-304-1', (select problem_id from problems where problem_code = 'LGL-304'), 'Roles Never Set', 'Behavioural', 'The team formed around people rather than jobs, so the line between legal judgement and product choice was never drawn.', 0.77, 'internal', 'Stage 0→1', '["legaltech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LGL-304-2', (select problem_id from problems where problem_code = 'LGL-304'), 'Overlap Feels Collaborative', 'Psychological', 'Everyone contributing everywhere feels like a good team, which hides that legal responsibility has no owner.', 0.70, 'internal', 'Stage 0→1', '["legaltech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LGL-304-3', (select problem_id from problems where problem_code = 'LGL-304'), 'Handovers Unwritten', 'Operational', 'What must be reviewed before wording reaches a client was never agreed in writing.', 0.69, 'internal', 'Stage 0→1', '["legaltech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-LGL-304-1', (select problem_id from problems where problem_code = 'LGL-304'), '["RC-LGL-304-1", "RC-LGL-304-2", "RC-LGL-304-3"]'::jsonb, 'Team Effectiveness', 'Legal & LegalTech — Role Clarity', '[]'::jsonb, '["Write down which decisions are legal judgement and which are product choice.", "Put one name against each group.", "Write what must be reviewed before any wording reaches a client."]'::jsonb, '[3, 4, 5]'::jsonb, '["legaltech"]'::jsonb, '["An unowned legal decision is a complaint waiting to happen.", "The review list is the handover."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-LGL-304-2', (select problem_id from problems where problem_code = 'LGL-304'), '["RC-LGL-304-1", "RC-LGL-304-2", "RC-LGL-304-3"]'::jsonb, 'Team Effectiveness', 'Legal & LegalTech — Role Clarity', '[]'::jsonb, '["Pick the decision type that caused the most confusion last quarter.", "Give it one owner and tell the team.", "Review that one alone next quarter."]'::jsonb, '[3, 4, 5]'::jsonb, '["legaltech"]'::jsonb, '["One boundary drawn properly beats a whole new structure."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
