insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('LGL-305', 'Every Judgement Call Comes Back to the Founder', 'Team & Leadership', 'internal', 'Whether a matter type is in scope, whether an output is safe to show, whether an edge case needs a human — all of it escalates, because none of it was written as criteria. The founder becomes the process.', 5, 9, '["All judgement calls escalate", "No written scope criteria", "Work waits on the founder", "Team stops deciding anything"]'::jsonb, 5, 'Decision Rights', 'decision_rights', '["legaltech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LGL-305-1', (select problem_id from problems where problem_code = 'LGL-305'), 'Rules Never Written', 'Operational', 'The founder''s legal judgement was never turned into criteria, so every case needs them personally.', 0.78, 'internal', 'Stage 0→1', '["legaltech"]'::jsonb) on conflict (root_cause_code) do nothing;
