insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LGL-305-3', (select problem_id from problems where problem_code = 'LGL-305'), 'No Safe Line to Delegate Across', 'Knowledge', 'There is no written line between what may be decided and what must escalate, so everything escalates.', 0.67, 'internal', 'Stage 0→1', '["legaltech"]'::jsonb) on conflict (root_cause_code) do nothing;
