insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('LGL-307', 'Selling Software, Running a Law Firm With a Login', 'Strategy & Planning', 'internal', 'The pitch is a product that scales. The reality is that a lawyer reviews every output before it goes out, so revenue grows only as fast as lawyers can be hired. Each review was justified by caution and together they are a firm.', 5, 9, '["Pitched as product, delivered with human review", "Every output reviewed by a lawyer", "Revenue grows only with headcount", "Margins look like a firm''s"]'::jsonb, 6, 'Plan and Vision', 'plan_to_vision_alignment', '["legaltech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LGL-307-1', (select problem_id from problems where problem_code = 'LGL-307'), 'Plan Never Checked Against the Goal', 'Strategic', 'Nobody holds what is actually delivered against what the company says it sells, so the drift is never seen.', 0.78, 'internal', 'Stage 0→1', '["legaltech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LGL-307-2', (select problem_id from problems where problem_code = 'LGL-307'), 'Each Review Looked Prudent', 'Behavioural', 'Every human check was justified by risk, and nobody counted what they cost together.', 0.73, 'internal', 'Stage 0→1', '["legaltech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-LGL-307-3', (select problem_id from problems where problem_code = 'LGL-307'), 'Goal Never Described as Rules', 'Knowledge', '"A product" was never written down as what must be true, so nothing can be tested against it.', 0.67, 'internal', 'Stage 0→1', '["legaltech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-LGL-307-1', (select problem_id from problems where problem_code = 'LGL-307'), '["RC-LGL-307-1", "RC-LGL-307-2", "RC-LGL-307-3"]'::jsonb, 'Strategic Focus', 'Legal & LegalTech — Plan and Vision', '[]'::jsonb, '["Count what share of outputs a lawyer reviews, and what that costs per client.", "Find the output type that is reviewed most and almost never changed.", "Stop reviewing that one, and measure what happens."]'::jsonb, '[3, 4, 5]'::jsonb, '["legaltech"]'::jsonb, '["A review that never changes anything is a cost, not a safeguard.", "Measure the one you are most confident about first."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-LGL-307-2', (select problem_id from problems where problem_code = 'LGL-307'), '["RC-LGL-307-1", "RC-LGL-307-2", "RC-LGL-307-3"]'::jsonb, 'Strategic Focus', 'Legal & LegalTech — Plan and Vision', '[]'::jsonb, '["Write what \"a product\" means for you in five specific things.", "Mark which are true today.", "Put the missing ones ahead of new features."]'::jsonb, '[3, 4, 5]'::jsonb, '["legaltech"]'::jsonb, '["A goal you cannot test delivery against is a slogan."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
