insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('LGL-308', 'A New Practice Area, a Rewrite and a Compliance Review Together', 'Strategy & Planning', 'internal', 'Expanding into a second area of law, rebuilding the platform and completing a client''s compliance review are all live. The compliance review is the one that gates the largest contract, and it has the same resources as the rest.', 5, 9, '["Several big pushes at once", "Rewrite competing for the same people", "Compliance review not prioritised", "Everything half-done"]'::jsonb, 6, 'Prioritisation', 'prioritization_discipline', '["legaltech"]'::jsonb) on conflict (problem_code) do nothing;
