-- LGL-301 · skill_stage_fit · A Fine Lawyer Who Has Never Priced a Product

-- LGL-302 · time_allocation_reality · Still Practising Law and Running the Company

-- LGL-303 · founder_dependency · Only the Founder Can Answer a Legal Question About the Product

-- LGL-304 · team_structure_role_clarity · Legal Review and Product Decisions Blur Together

-- LGL-305 · decision_rights · Every Judgement Call Comes Back to the Founder

-- LGL-306 · hiring_repeatability · Hiring Lawyers the Founder Trained, and No One Else

-- LGL-307 · plan_to_vision_alignment · Selling Software, Running a Law Firm With a Login

-- LGL-308 · prioritization_discipline · A New Practice Area, a Rewrite and a Compliance Review Together

-- LGL-309 · institutional_memory · Why Each Client Left, and Each Objection, Lives in Email

-- Self-check inside the transaction. If any count is short, this raises and the
-- whole batch rolls back rather than leaving a partial load behind.
do $$
declare p int; r int; qn int; i int; m int;
begin
  select count(*) into p from problems where problem_code ~ '^(HRT|TRD|MFG|SAS|LGL)-3[0-9][0-9]$';
  select count(*) into r from root_causes where root_cause_code ~ '^RC-(HRT|TRD|MFG|SAS|LGL)-3[0-9][0-9]-[0-9]$';
  select count(*) into qn from questions where question_code ~ '^S(0|01|10)-(HRT|TRD|MFG|SAS|LGL)-3[0-9][0-9]-[0-9]$';
  select count(*) into i from interventions where intervention_code ~ '^INT-(HRT|TRD|MFG|SAS|LGL)-3[0-9][0-9]-[0-9]$';
  select count(*) into m from question_industry_mapping qim join questions qq on qq.question_id=qim.question_id
    where qq.question_code ~ '^S(0|01|10)-(HRT|TRD|MFG|SAS|LGL)-3[0-9][0-9]-[0-9]$';
  if p <> 45 or r <> 135 or qn <> 270 or i <> 90 or m <> 270 then
    raise exception 'batch 4 incomplete: problems=% root_causes=% questions=% interventions=% mappings=% (expected 45/135/270/90/270)', p, r, qn, i, m;
  end if;
  raise notice 'batch 4 ok: 45 problems, 135 root causes, 270 questions, 90 interventions, 270 mappings';
end $$;

COMMIT;
